<script setup lang="ts">
import {computed,ref,watch,defineAsyncComponent,onErrorCaptured} from 'vue';
import {useRouter,useRoute} from 'vue-router';
import {usePlatform} from './stores/platform';import {groups,reportTypes} from './domain';import {apiMode} from './api/client';import {pageNames} from './router';import FormDialog from './components/FormDialog.vue';
const p=usePlatform(),router=useRouter(),route=useRoute(),account=ref(apiMode==='mock'?'demo.admin':''),password=ref(apiMode==='mock'?'demo123':''),messages=ref(false),failure=ref('');
const pages={dashboard:defineAsyncComponent(()=>import('./pages/DashboardPage.vue')),search:defineAsyncComponent(()=>import('./pages/SearchPage.vue')),analysis:defineAsyncComponent(()=>import('./pages/AnalysisPage.vue')),datasets:defineAsyncComponent(()=>import('./pages/DatasetsPage.vue')),map:defineAsyncComponent(()=>import('./pages/MapPage.vue')),operations:defineAsyncComponent(()=>import('./pages/OperationsPage.vue')),admin:defineAsyncComponent(()=>import('./pages/AdminPage.vue')),library:defineAsyncComponent(()=>import('./pages/LibraryPage.vue')),watch:defineAsyncComponent(()=>import('./pages/WatchPage.vue')),profiles:defineAsyncComponent(()=>import('./pages/ProfilesPage.vue')),service:defineAsyncComponent(()=>import('./pages/ServicePage.vue'))};
const component=computed(()=>p.active==='系统首页'?pages.dashboard:['围栏检索','车牌检索','MAC检索','人像检索'].includes(p.active)?pages.search:['伴随任务','碰撞任务','区域统计'].includes(p.active)?pages.analysis:p.active==='数据运算'?pages.datasets:['地图研判','设备分布'].includes(p.active)?pages.map:p.active==='运维首页'?pages.operations:['场所管理','设备管理','用户管理','角色管理'].includes(p.active)?pages.admin:p.active==='人员库'?pages.library:['综合布控','告警结果'].includes(p.active)?pages.watch:['图码档案','车码档案','数据态势'].includes(p.active)?pages.profiles:pages.service);
const groupForPage=()=>Object.keys(groups).find(g=>groups[g]?.includes(p.active));
const datasetPages=['围栏检索','车牌检索','MAC检索','人像检索','地图研判','伴随任务','碰撞任务','区域统计'];
let routeSyncs=0;
async function syncRoute(page:string){routeSyncs++;try{await router.replace('/page/'+pageNames.indexOf(page));}finally{routeSyncs--;}}
watch(()=>p.session,session=>{if(!session)messages.value=false;});
watch(()=>p.active,page=>{failure.value='';void syncRoute(page);});
watch(()=>route.params.id,id=>{if(routeSyncs)return;const page=pageNames[Number(id)];if(page&&p.session&&page!==p.active){if(p.allowed(page))p.navigate(page);else void syncRoute(p.active);}});
watch(()=>p.modal.model.region,region=>{if(apiMode==='mock'&&p.modal.step===0){const opts=[...new Set(p.db.devices.filter(d=>d.region===region).map(d=>d.group))];const field=p.modal.fields.find(f=>f.key==='group');if(field)field.options=opts;if(!opts.includes(String(p.modal.model.group)))p.modal.model.group=opts[0]||'';}}, {immediate:true});
watch(()=>[p.modal.model.mode,p.modal.model.type],()=>{if(p.modal.title==='新增运维报表'){const multi=p.modal.model.mode==='多报表',type=String(p.modal.model.type);p.modal.fields=p.modal.fields.filter(f=>!['type','subtype','subtypes'].includes(f.key));const content=multi?[{key:'subtypes',label:'多报表类型（默认全选）',options:reportTypes,multiple:true}]:[{key:'type',label:'报表类型',options:['设备报表','数据报表','系统报表']},{key:'subtype',label:'报表内容',options:type==='设备报表'?reportTypes.slice(0,2):type==='系统报表'?reportTypes.slice(7):reportTypes.slice(2,7)}];p.modal.fields.splice(2,0,...content);const valid=type==='设备报表'?reportTypes.slice(0,2):type==='系统报表'?reportTypes.slice(7):reportTypes.slice(2,7);if(!valid.includes(String(p.modal.model.subtype)))p.modal.model.subtype=valid[0];}});
onErrorCaptured(error=>{failure.value=error.message;console.error(error);return false;});
async function enter(){await p.login(account.value,password.value);password.value='';if(p.session)await syncRoute('系统首页');}
async function switchIdentity(value:string){await p.logout();account.value=value;password.value='demo123';await enter();}
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file)await p.readImport(file);}
</script>
<template><div v-if="!p.session" class="login-screen"><section class="login-card"><div class="brand-mark">数</div><h1>多维数据分析平台</h1><p class="muted">Vue 3 · TypeScript · {{apiMode==='mock'?'前端演示原型':'后端接口模式'}}</p><el-form label-position="top" @submit.prevent="enter"><el-form-item label="登录账号"><el-input v-model="account" autocomplete="username" aria-label="登录账号"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" autocomplete="current-password" show-password aria-label="密码"/></el-form-item><el-alert v-if="p.error" :title="p.error" type="error" :closable="false"/><el-button type="primary" class="login-submit" native-type="submit" :loading="p.busy">登录</el-button></el-form><template v-if="apiMode==='mock'"><p class="hint">仅使用合成演示数据，算法、短信、邮件及远控均为模拟。</p><p class="muted">演示账号：admin / analyst / secret / test<br/>完整账号为 demo.角色名；密码 demo123</p></template></section></div><div v-else class="app-shell"><header class="topbar"><div class="brand"><span class="brand-mark">数</span><strong>多维数据分析平台</strong></div><el-tag :type="apiMode==='mock'?'warning':'success'">{{apiMode==='mock'?'Mock 演示':'HTTP 接口'}}</el-tag><div class="spacer"/><el-button class="message-trigger" @click="messages=true;p.loadMessages()">平台消息 {{apiMode==='http'?p.remote.messageTotal:p.db.messages.filter(m=>!m.read).length}}</el-button><el-select v-if="apiMode==='mock'" :model-value="p.currentUser?.account" class="identity" aria-label="演示身份" @update:model-value="switchIdentity"><el-option v-for="u in p.db.users.filter(u=>u.enabled)" :key="u.id" :label="u.name+' · '+p.db.roles.find(r=>r.id===u.role)?.name" :value="u.account"/></el-select><span v-else>{{p.currentUser?.name}}</span><el-button @click="p.passwordForm()">修改密码</el-button><el-button @click="p.logout">退出</el-button></header><aside class="sidebar"><nav aria-label="平台导航"><template v-for="(items,group) in groups" :key="group"><div v-if="items.some(p.allowed)" class="nav-group">{{group}}</div><button v-for="name in items.filter(p.allowed)" :key="name" :class="{active:p.active===name}" @click="p.navigate(name)">{{name}}</button></template></nav></aside><main class="main"><div class="page-title"><div><p class="breadcrumb">平台 / {{groupForPage()}} / {{p.active}}</p><h1>{{p.active}}</h1></div><div class="spacer"/><el-button v-if="p.detail||p.history.length" @click="p.back">返回上一页</el-button></div><el-alert v-if="apiMode==='mock'" class="mode-banner" title="前端原型：数据与算法结果均为虚构，通知和设备操作不会实际执行。" type="info" :closable="false"/><el-alert v-if="apiMode==='http'&&p.remote.error" :title="'接口加载失败：'+p.remote.error+(p.remote.traceId?' · Trace ID：'+p.remote.traceId:'')" type="error" :closable="false" show-icon/><el-alert v-if="failure" :title="'页面异常：'+failure" type="error" :closable="false"/><Suspense><component :is="component" :key="p.active"/><template #fallback><el-skeleton :rows="8" animated/></template></Suspense><button v-if="datasetPages.includes(p.active)&&!p.drawer" class="dataset-tab" @click="p.drawer=true">数据集 ◂</button><el-drawer v-model="p.drawer" title="数据集" size="340px"><el-button type="primary" @click="p.addDataset(p.currentCaptureResults())">添加当前结果</el-button><article v-for="set in p.db.datasets" :key="set.id" class="dataset-item"><b>{{set.name}}</b><p class="muted">{{set.items.length}} 条</p><el-button @click="p.selectedDataset=set.id;p.navigate('数据运算')">查看数据运算</el-button></article><el-button type="primary" @click="p.navigate('数据运算')">进入数据运算</el-button></el-drawer></main></div><FormDialog :visible="p.modal.visible" :title="p.modal.title" :fields="p.modal.fields" :model="p.modal.model" :error="p.modal.error" :busy="p.modal.busy" :submit="p.modal.submit" @close="p.modal.visible=false" @save="p.saveForm"><div v-if="p.modal.step>=0" class="wide"><el-steps :active="p.modal.step" :space="220"><el-step title="选择设备分组"/><el-step title="选择设备"/><el-step title="设置参数"/></el-steps></div><dl v-if="p.modal.info.length" class="wide info-list"><template v-for="([label,value],i) in p.modal.info" :key="i"><dt>{{label}}</dt><dd>{{typeof value==='object'?JSON.stringify(value):value}}</dd></template></dl><div class="wide"><el-button v-if="p.modal.model.configId" @click="p.formConfig(String(p.modal.model.configId))">编辑任务</el-button><el-button v-if="p.modal.model.notificationId" @click="p.formNotification(String(p.modal.model.notificationId))">编辑信息</el-button></div></FormDialog><el-dialog v-model="p.importState.visible" :title="'导入 · '+({libraries:'人员库',devices:'设备信息',datasets:'数据集'} as Record<string,string>)[p.importState.scope]" width="800px" @close="p.cancelImport"><p v-if="apiMode==='http'" class="hint">{{p.importState.policyText}}</p><p v-else class="hint">模板 v1 · JSON / CSV / XLSX · 最多 5 MB、1000 行；全部校验通过后一次性写入。</p><div class="actions"><el-button @click="p.template">下载导入模板</el-button><input type="file" accept=".json,.csv,.xlsx" aria-label="选择导入文件" @change="readFile"/></div><p>{{p.importState.name}}{{apiMode==='mock'?' · '+p.importState.rows.length+' 行':''}}</p><el-table v-if="apiMode==='http'&&p.importState.template" :data="p.importState.template.columns"><el-table-column prop="name" label="字段"/><el-table-column prop="label" label="说明"/><el-table-column prop="required" label="必填"/><el-table-column prop="description" label="格式要求"/></el-table><pre v-if="apiMode==='mock'" class="import-preview">{{JSON.stringify(p.importState.rows.slice(0,5),null,2)}}</pre><el-alert v-if="p.importState.error" type="error" :title="p.importState.error" :closable="false"/><template #footer><el-button @click="p.cancelImport">取消</el-button><el-button type="primary" :loading="p.importState.busy" @click="p.applyImport">确认导入</el-button></template></el-dialog><el-drawer v-model="messages" title="平台消息" size="420px"><el-empty v-if="!p.db.messages.length" description="暂无消息"/><el-button v-if="apiMode==='http'&&p.remote.messageCursor" @click="p.loadMessages(true)">加载更多</el-button><article v-for="m in p.db.messages" :key="m.id" class="message-item" @click="apiMode==='mock'&&(m.read=true,p.commit('消息已读'))"><h3>{{m.title}}</h3><p>{{m.content}}</p><p class="muted">{{m.time}} · {{m.read?'已读':'未读'}}</p></article></el-drawer></template>

